import {SchoolTHREE as THREE} from './core.js';
const related=(a,b)=>{for(let n=a;n;n=n.parent)if(n===b)return true;for(let n=b;n;n=n.parent)if(n===a)return true;return false;};
const visible=o=>{for(let n=o;n;n=n.parent)if(!n.visible)return false;return true;};
const character=o=>{for(let n=o;n;n=n.parent)if(n.userData.spec||n.userData.arms||n.userData.neighbour!==undefined)return true;return false;};
const points=box=>{const c=box.getCenter(new THREE.Vector3()),s=box.getSize(new THREE.Vector3());return [c,c.clone().add(new THREE.Vector3(0,s.y*.3,0)),c.clone().add(new THREE.Vector3(s.x*.25,0,0)),c.clone().add(new THREE.Vector3(-s.x*.25,0,0))];};
export class ActivityCamera{
 constructor(){this.clones=new WeakMap();this.changed=[];this.key='';this.cache=null;this.ray=new THREE.Ray();this.probe=new THREE.Vector3();this.testCamera=new THREE.PerspectiveCamera(55,1,.1,600);}
 restore(){for(const [mesh,material]of this.changed)mesh.material=material;this.changed=[];}
 reset(){this.restore();this.key='';this.cache=null;}
 prepare(roots,player,focus){this.restore();player.updateWorldMatrix(true,true);this.player=player;this.subjects=focus.filter(o=>o&&visible(o));this.entries=[];for(const node of [...roots,player]){if(!visible(node))continue;const box=new THREE.Box3().setFromObject(node);if(box.isEmpty()||box.max.y<.18||box.getSize(new THREE.Vector3()).y<.05)continue;this.entries.push({node,box});}this.playerBox=new THREE.Box3().setFromObject(player);this.bounds=this.playerBox.clone();this.targets=points(this.playerBox).map(point=>({point,owner:player}));for(const node of this.subjects){const box=new THREE.Box3().setFromObject(node);if(box.isEmpty())continue;this.bounds.union(box);this.targets.push({point:box.getCenter(new THREE.Vector3()),owner:node});}}
 blocks(origin,target){this.ray.set(origin,target.point.clone().sub(origin).normalize());const distance=origin.distanceTo(target.point),hits=[];for(const e of this.entries){if(related(e.node,target.owner)||e.box.containsPoint(target.point))continue;const hit=this.ray.intersectBox(e.box,this.probe);if(hit&&origin.distanceTo(hit)<distance-.12)hits.push(e);}return hits;}
 score(origin){let n=0;for(const target of this.targets)n+=this.blocks(origin,target).length;return n;}
 solve(camera,preferred,look,position,{key='',force=false}={}){const cacheKey=key+':'+camera.aspect.toFixed(3);if(!force&&this.key===cacheKey&&this.cache){position.copy(this.cache.position);look.copy(this.cache.look);return;}
 const centre=this.bounds.getCenter(new THREE.Vector3()),size=this.bounds.getSize(new THREE.Vector3());const direction=preferred.clone().sub(centre),base=Math.atan2(direction.x,direction.z);const tan=Math.tan(THREE.MathUtils.degToRad(camera.fov)/2),test=this.testCamera;Object.assign(test,{fov:camera.fov,aspect:camera.aspect,zoom:1});test.updateProjectionMatrix();let best=null;
 for(const yaw of [0,-Math.PI/4,Math.PI/4,-Math.PI/2,Math.PI/2,-3*Math.PI/4,3*Math.PI/4,Math.PI])for(const elevation of [.48,.76,1.02,1.25]){const angle=base+yaw,side=new THREE.Vector3(Math.sin(angle),0,Math.cos(angle));const horizontal=Math.abs(side.z)*size.x+Math.abs(side.x)*size.z;const depth=Math.abs(side.x)*size.x+Math.abs(side.z)*size.z;const distance=Math.max(5.5,horizontal/(2*tan*camera.aspect*.69),size.y/(2*tan*.69))+depth*.55;
  const pos=centre.clone().addScaledVector(side,distance*Math.cos(elevation));pos.y=centre.y+distance*Math.sin(elevation);pos.x=THREE.MathUtils.clamp(pos.x,-18.8,18.8);pos.z=THREE.MathUtils.clamp(pos.z,-12.7,14.2);pos.y=THREE.MathUtils.clamp(pos.y,2.4,10.1);test.position.copy(pos);test.lookAt(centre);test.updateMatrixWorld(true);let clipped=0;for(const x of [this.bounds.min.x,this.bounds.max.x])for(const y of [this.bounds.min.y,this.bounds.max.y])for(const z of [this.bounds.min.z,this.bounds.max.z]){const p=new THREE.Vector3(x,y,z).project(test);if(Math.abs(p.x)>.88||Math.abs(p.y)>.88||p.z>1)clipped++;}
  const blocked=this.score(pos),avatar=this.targets.filter(t=>t.owner!==this.player&&this.blocks(pos,t).some(e=>e.node===this.player)).length,cost=avatar*100000+blocked*100+clipped*1000000+Math.abs(yaw)*.3+Math.abs(elevation-.65);if(!best||cost<best.cost)best={position:pos,look:centre.clone(),cost,blocked};}
 this.key=cacheKey;this.cache=best;position.copy(best.position);look.copy(best.look);}
 guard(camera){this.restore();const blocked=new Set();for(const e of this.entries)if(e.node.userData.playmatFence&&e.box.intersectsBox(this.playerBox))blocked.add(e.node);for(const target of this.targets)for(const e of this.blocks(camera.position,target))if(!character(e.node)&&!this.subjects.some(s=>related(s,e.node)))blocked.add(e.node);for(const node of blocked)node.traverse(mesh=>{if(!mesh.isMesh||character(mesh)||!visible(mesh))return;const original=mesh.material;let cached=this.clones.get(mesh);if(!cached||cached.original!==original){const list=(Array.isArray(original)?original:[original]).map(m=>{const clone=m.clone();clone.transparent=true;clone.opacity=.06;clone.depthWrite=false;return clone;});cached={original,material:Array.isArray(original)?list:list[0]};this.clones.set(mesh,cached);}this.changed.push([mesh,original]);mesh.material=cached.material;});}
 avatarBlocks(camera){return this.targets.some(target=>target.owner!==this.player&&this.blocks(camera.position,target).some(e=>e.node===this.player));}
}
